The expected final value is 800000. On failure, compare_exchange_weak overwrites expected with the observed counter value; the next attempt must recompute desired from that updated value. Weak CAS can also fail spuriously, so it needs a retry loop. Relaxed ordering is sufficient because the counter publishes no other memory; joining all threads ensures completion before checking the result.

```cpp
#include <atomic>
#include <cassert>
#include <iostream>
#include <limits>
#include <thread>
#include <vector>

class Counter {
public:
    void increment() noexcept {
        unsigned expected = value_.load(std::memory_order_relaxed);
        while (!value_.compare_exchange_weak(
            expected, expected + 1u,
            std::memory_order_relaxed,
            std::memory_order_relaxed)) {
            // Failure updates expected; recompute expected + 1 next time.
        }
    }

    unsigned value() const noexcept {
        return value_.load(std::memory_order_relaxed);
    }

private:
    std::atomic<unsigned> value_{0u};
};

int main() {
    constexpr unsigned thread_count = 8u;
    constexpr unsigned increments_per_thread = 100000u;
    static_assert(std::numeric_limits<unsigned>::max() >= 800000ULL,
                  "unsigned must represent 800000");
    constexpr unsigned expected_final =
        thread_count * increments_per_thread;

    Counter counter;
    assert(counter.value() == 0u);

    std::vector<std::thread> threads;
    threads.reserve(thread_count);
    for (unsigned i = 0; i < thread_count; ++i) {
        threads.emplace_back([&counter] {
            for (unsigned j = 0; j < increments_per_thread; ++j) {
                counter.increment();
            }
        });
    }

    for (auto& thread : threads) {
        thread.join();
    }

    const unsigned result = counter.value();
    assert(result == expected_final);
    if (result != expected_final) {
        return 1; // Also check when assertions are disabled.
    }
    std::cout << result << '\n';
    return 0;
}
```

Compile with: `g++ -std=c++17 -O2 -pthread counter.cpp -o counter`

