```cpp
#include <atomic>
#include <cassert>
#include <cstdint>
#include <iostream>
#include <thread>
#include <array>

class Counter {
public:
    void increment() noexcept {
        std::uint64_t expected = value_.load(std::memory_order_relaxed);
        while (!value_.compare_exchange_weak(
            expected, expected + 1,
            std::memory_order_relaxed,
            std::memory_order_relaxed)) {
            // Failure refreshes expected; the next attempt
            // recomputes the desired value from it.
        }
    }

    std::uint64_t load() const noexcept {
        return value_.load(std::memory_order_relaxed);
    }

private:
    std::atomic<std::uint64_t> value_{0};
};

int main() {
    constexpr std::size_t thread_count = 8;
    constexpr std::uint64_t increments_per_thread = 100000;
    constexpr std::uint64_t expected_final =
        thread_count * increments_per_thread;
    static_assert(expected_final == 800000);

    Counter counter;
    assert(counter.load() == 0);

    std::array<std::thread, thread_count> threads;
    for (auto& thread : threads) {
        thread = std::thread([&counter] {
            for (std::uint64_t i = 0; i < increments_per_thread; ++i) {
                counter.increment();
            }
        });
    }

    for (auto& thread : threads) {
        thread.join();
        assert(!thread.joinable());
    }

    const auto result = counter.load();
    assert(result == expected_final);
    std::cout << result << '\n';
    return result == expected_final ? 0 : 1;
}
```

